            var maxPossible = 0;
            var allDecs = [round.d1, round.d2, round.d3];
            for (var k = 0; k < allDecs.length; k++) {
                var bestTotal = 0;
                for (var m = 0; m < allDecs[k].options.length; m++) {
                    var optTotal = allDecs[k].options[m].learning + Math.max(0, allDecs[k].options[m].safety) + allDecs[k].options[m].risk;
                    if (optTotal > bestTotal) bestTotal = optTotal;
                }
                maxPossible += bestTotal;
            }
            var actualTotal = learningGain + Math.max(0, safetyGain) + riskGain;
            var roundScore = maxPossible > 0 ? Math.round((actualTotal / maxPossible) * 100) : 0;

            state.domainState.learningHistory.push(state.domainState.learningScore);
            state.domainState.safetyHistory.push(state.domainState.safetyScore);
            state.domainState.riskHistory.push(state.domainState.riskScore);
            state.domainState.revenueHistory.push(state.domainState.revenueProtected);
            state.domainState.roundScoreHistory.push(roundScore);

            // Platform score: running average of roundScore so far, same metric getPerformanceSummary averages into avgScore
            var scoreSum = 0;
            for (var si = 0; si < state.domainState.roundScoreHistory.length; si++) {
                scoreSum += state.domainState.roundScoreHistory[si];
            }
            var overallScore = Math.round(scoreSum / state.domainState.roundScoreHistory.length);
            overallScore = Math.max(0, Math.min(100, overallScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackPanel.style.display = 'block';
                var fbLevel = '_low';
                if (roundScore >= 80) fbLevel = '_high';
                else if (roundScore >= 50) fbLevel = '_mid';
                feedbackText.innerHTML = window.mySimulation.t(round.feedbackKey + fbLevel);
            }

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                learningGain: learningDelta,
                safetyGain: safetyDelta,
                riskGain: riskDelta,
                revenueGain: revenueGain,
                learningScore: state.domainState.learningScore,
                safetyScore: state.domainState.safetyScore,
                riskScore: state.domainState.riskScore,
                revenueProtected: state.domainState.revenueProtected
            };
        }

