        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var lastEntry = history[history.length - 1];
            var finalLearning = lastEntry.results ? lastEntry.results.learningScore || 0 : 0;
            var finalSafety = lastEntry.results ? lastEntry.results.safetyScore || 0 : 0;
            var finalRisk = lastEntry.results ? lastEntry.results.riskScore || 0 : 0;
            var finalRevenue = lastEntry.results ? lastEntry.results.revenueProtected || 0 : 0;

            var performance = 'Needs Improvement';
            if (avgScore >= 80 && finalLearning >= 70 && finalSafety >= 60) performance = 'Excellent';
            else if (avgScore >= 60 && finalLearning >= 50) performance = 'Good';
            else if (avgScore >= 40) performance = 'Fair';

            var insights = [];
            if (finalLearning >= 70) {
                insights.push('Strong systemic analysis — the organization can learn from failure effectively.');
            } else {
                insights.push('The analysis stayed too close to surface-level causes. Push deeper with the 5 Whys next time.');
            }
            if (finalSafety >= 60) {
                insights.push('High psychological safety — team members feel safe reporting problems early.');
            } else {
                insights.push('Low psychological safety may cause future problems to be hidden until they escalate.');
            }
            if (finalRevenue >= 700000) {
                insights.push('Significant revenue protected through proactive risk mitigation.');
            } else {
                insights.push('More revenue could have been protected with stronger preventive actions.');
            }

            return {
                avgScore: avgScore,
                finalLearning: finalLearning,
                finalSafety: finalSafety,
                finalRisk: finalRisk,
                revenueProtected: finalRevenue,
                performance: performance,
                insights: insights
            };
        }

