        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var decisionGroups = [
                { label: 'decision1Label', select: 'decision1Input', config: round.d1 },
                { label: 'decision2Label', select: 'decision2Input', config: round.d2 },
                { label: 'decision3Label', select: 'decision3Input', config: round.d3 }
            ];

            for (var i = 0; i < decisionGroups.length; i++) {
                var grp = decisionGroups[i];
                var labelEl = document.getElementById(grp.label);
                if (labelEl) labelEl.innerHTML = t(grp.config.labelKey);
                var selectEl = document.getElementById(grp.select);
                if (selectEl) {
                    selectEl.innerHTML = '';
                    for (var j = 0; j < grp.config.options.length; j++) {
                        var opt = grp.config.options[j];
                        var optEl = document.createElement('option');
                        optEl.value = opt.value;
                        optEl.textContent = t(opt.textKey);
                        selectEl.appendChild(optEl);
                    }
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new DespuesAdapter(), {
            simulationType: 'despues_aar',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

